import{_ as a,o as t,c as r,h as o}from"./chunks/framework.DC5NoOP7.js";const u=JSON.parse('{"title":"Rethinking Education with AI","description":"A research agenda on AI-assisted learning, assessment, independent judgment, and accountable human–AI collaboration.","frontmatter":{"title":"Rethinking Education with AI","description":"A research agenda on AI-assisted learning, assessment, independent judgment, and accountable human–AI collaboration."},"headers":[],"relativePath":"research.md","filePath":"research.md"}'),s={name:"research.md"};function n(i,e,l,c,d,h){return t(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="rethinking-education-with-ai" tabindex="-1">Rethinking Education with AI <a class="header-anchor" href="#rethinking-education-with-ai" aria-label="Permalink to &quot;Rethinking Education with AI&quot;">​</a></h1><p><strong>If AI can produce much of the assignment, what should education teach—and what evidence would show that learning happened?</strong></p><p>I&#39;m interested in the consequences of AI for teaching, assessment, curriculum, and human judgment. My approach starts with a practical problem, builds a concrete example, and asks what we can actually learn from it.</p><p>This page describes <strong>questions and possible directions for study</strong>. It is not a list of completed experiments, peer-reviewed findings, or an approved dissertation proposal.</p><h2 id="three-research-questions" tabindex="-1">Three research questions <a class="header-anchor" href="#three-research-questions" aria-label="Permalink to &quot;Three research questions&quot;">​</a></h2><h3 id="_1-does-ai-assisted-work-develop-transferable-understanding" tabindex="-1">1. Does AI-assisted work develop transferable understanding? <a class="header-anchor" href="#_1-does-ai-assisted-work-develop-transferable-understanding" aria-label="Permalink to &quot;1. Does AI-assisted work develop transferable understanding?&quot;">​</a></h3><p>An AI-generated solution can be correct even when a learner cannot explain or independently adapt it. One direction for study is to compare learners&#39; work with AI assistance against their performance on new tasks without that assistance.</p><p><strong>Possible evidence:</strong> explanation quality, independent debugging, transfer tasks, test design, and the ability to identify model errors. A convincing study would require appropriate comparison groups, controls, and institutional review where applicable.</p><h3 id="_2-what-should-assessment-measure-when-ai-produces-artifacts" tabindex="-1">2. What should assessment measure when AI produces artifacts? <a class="header-anchor" href="#_2-what-should-assessment-measure-when-ai-produces-artifacts" aria-label="Permalink to &quot;2. What should assessment measure when AI produces artifacts?&quot;">​</a></h3><p>A finished program, essay, or design may no longer be sufficient evidence of individual learning. Rather than assuming that more surveillance solves this problem, we can investigate assessment built around judgment, transparent process, peer review, defensible choices, and reliable execution.</p><p><strong>Possible evidence:</strong> separately evaluated process artifacts, oral or written explanations, novel transfer tasks, and agreement among assessors. We should measure the costs and limitations of these approaches as well as potential benefits.</p><h3 id="_3-how-should-people-govern-ai-collaborators" tabindex="-1">3. How should people govern AI collaborators? <a class="header-anchor" href="#_3-how-should-people-govern-ai-collaborators" aria-label="Permalink to &quot;3. How should people govern AI collaborators?&quot;">​</a></h3><p>Useful AI systems increasingly perform sequences of actions, not just supply text. That creates questions about authority, evidence, error recovery, and the division of responsibility between human and machine.</p><p><strong>Possible evidence:</strong> task-completion accuracy, incorrect claims of completion, revision cycles, the traceability of decisions, and human attention required to supervise a workflow.</p><p>My <a href="https://github.com/kaw393939/ordo" target="_blank" rel="noreferrer">Ordo project</a> explores specifications for local-first, evidence-governed AI workflows. Its documented architecture is a design case—not proof of a deployed runtime or validated outcome.</p><h2 id="from-practice-to-evidence" tabindex="-1">From practice to evidence <a class="header-anchor" href="#from-practice-to-evidence" aria-label="Permalink to &quot;From practice to evidence&quot;">​</a></h2><p>The work follows a deliberately repeatable cycle:</p><ol><li><strong>Formulate:</strong> What problem and learning outcome are we actually investigating?</li><li><strong>Specify:</strong> What would count as success, failure, and evidence?</li><li><strong>Build:</strong> Create a lesson, system, or small study that can be inspected.</li><li><strong>Evaluate:</strong> Compare alternatives, gather observations, and report uncertainty.</li><li><strong>Revise:</strong> Improve the design while separating observation from interpretation.</li></ol><p>This is also my teaching philosophy in a more research-oriented form: practice informs theory, and theory should help us design better practice.</p><h2 id="work-that-informs-the-questions" tabindex="-1">Work that informs the questions <a class="header-anchor" href="#work-that-informs-the-questions" aria-label="Permalink to &quot;Work that informs the questions&quot;">​</a></h2><ul><li><a href="https://github.com/kaw393939/is117-brand-studio" target="_blank" rel="noreferrer">IS117 Brand Studio</a>: an educational template for AI-assisted design and reflection.</li><li><a href="https://github.com/kaw393939/educational-design-system" target="_blank" rel="noreferrer">Educational Design System</a>: a documentation-first approach to repeatable educational experiences.</li><li><a href="https://github.com/kaw393939/everyday-ai-cli" target="_blank" rel="noreferrer">Everyday AI CLI</a>: practical AI tools for accessible workflows.</li><li><a href="https://github.com/kaw393939/ordo" target="_blank" rel="noreferrer">Ordo</a>: a documented concept for human-directed, auditable AI orchestration; runtime implementation remains an open milestone.</li></ul><p>These are design and implementation artifacts, not substitutes for empirical validation. Research claims should be tied to methods, evidence, and appropriately qualified results.</p><h2 id="collaborate-or-discuss" tabindex="-1">Collaborate or discuss <a class="header-anchor" href="#collaborate-or-discuss" aria-label="Permalink to &quot;Collaborate or discuss&quot;">​</a></h2><p>I&#39;m interested in conversations connecting AI education, software engineering, instructional design, and research methods. You can find my <a href="https://people.njit.edu/profile/kwilliam" target="_blank" rel="noreferrer">NJIT faculty profile</a> or <a href="/#conversation">start a public GitHub conversation</a>. Please do not put private or student information in a public issue.</p><p><a href="/teaching">See how I teach AI</a> · <a href="/#projects">Selected public projects</a></p><p><em>Personal research interests. No completed study, institutional endorsement, or formal doctoral appointment is implied.</em></p>',26)])])}const m=a(s,[["render",n]]);export{u as __pageData,m as default};
